    def modify_mass_site(self, assign_to_site, dist_names=None, working_sets=None, maintenance_regions=None,
                         scope_dn_range=None, object_classes=None, overwrite_site_values=None, ui_values=None,
                         verbose=True, schedule=None, ignore_errors=False, timeout=7200, alias=None):
        """
        Site objects are created/modified and managed objects specified by the given scope are assigned to them.
        The operation scope must be defined with one or more of the following parameters: ``dist_names``,
        ``working_sets``, ``maintenance_regions`` or ``scope_dn_range``. The operation scope is a sum of DNs
        retrieved from ``dist_names``, ``working_sets``, ``maintenance_regions`` and ``scope_dn_range``.

        Operation supports:
            - assigning managed objects given in scope to existing site identified by ``siteId`` parameter,
            - modifying existing site when ``overwrite_site_values`` flag is set to ``True`` and assigning managed objects
                given in scope to it,
            - creation of new site and assigning managed objects given in scope to it.

        :param dict(string,string) assign_to_site: Specifies the Site to which the given scope is assigned.
            ``siteId`` parameter is mandatory to create/identify the Site, other parameters are optional.
            If specified ``siteId`` does not exist it will be created with provided parameters. If the ``siteId`` already
            exists and ``overwrite_site_values`` parameter is set to ``False``, the rest of defined parameters will be omitted.
        :param string|list(string) dist_names: Specifies the scope of the operation as exact DNs.
        :param string|list(string) working_sets: Specifies the scope of the operation as defined in given working
            sets. The objects retrieved from the given working sets are added into the operation scope.
        :param string|list(string) maintenance_regions: Specifies the scope of the operation as defined in given
            maintenance regions.
        :param string scope_dn_range: Specifies the scope of the operation as a DN range.
            The range must include comma-separated start and end DNs of the operational objects, e.g.,
            ``PLMN-PLMN/MRBTS-2500,PLMN-PLMN/MRBTS-2510``.
        :param string|list(string) object_classes: Specifies the object classes as qualified class abbreviation
            (e.g., ``NOKLTE:LNCEL``, ``NOKLTE:LNBTS``). When object_classes are given, the operation will assign to site
            objects that fulfill the following criteria:

                - object matches the one of the given objectClasses and
                - object belongs to the operation scope or object is the descendant of any object from the operation scope.

        :param bool overwrite_site_values: Specifies whether site parameter values should be overwritten
            when site with provided siteId already exists.
        :param bool ui_values: Specifies if parameter values are given as UI values. If this parameter is not defined
            internal values are used.
        :param bool verbose: If ``True``, returns more detailed output from executed operation.
        :param string schedule: ``prepare_schedule`` method should be used to obtain correct value.
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails.
        :param int|string timeout: Timeout for executing operation.
        :param string alias: Netact instance name. Default value is ``default``.
        :return: Operation output.
        """
        return self.store.get(alias).modify_mass_site(
            assign_to_site, dist_names, working_sets, maintenance_regions, scope_dn_range, object_classes,
            overwrite_site_values, ui_values, to_boolean(verbose), schedule, to_boolean(ignore_errors),
            time_to_seconds(timeout))

