    def reset_ne(self, dist_names=None, working_sets=None, class_filter_include=None, parameters=None, dry_run=False,
                 verbose=True, schedule=None, ignore_errors=False, timeout=900, alias=None, allow_vcu_reset=None):
        """
        This operation is used for resetting SBTS and ASiR objects **SBTS23R3 onward**. A temporary plan is created
        and provisioned to the network element. In dry run, create the plan only without triggering the reset.
        The reset is executed using best effort mode, meaning that the reset operation is not stopped at the first
        error but it is continued for all managed objects.

        .. note::
            - The operation is supported since `FP1112`
            - The operation cannot be interrupted.
            - For information on the supported object classes, use :meth:`reset_ne_help` method.

        :param string|list(string) dist_names: Specifies the scope of the operation.
            At least one of the parameters ``dist_names`` or ``working_sets`` must be defined.
            It is possible to define multiple target object instances for one NE if the reset object class is the same.
        :param string|list(string) working_sets: Specifies the scope of the operation.
            At least one of the parameters ``dist_names`` or ``working_sets`` must be defined.
            It is possible to define multiple target object instances for one NE if the reset object class is the same.
        :param string|list(string) class_filter_include: Specifies the object classes that are included to the reset
            operation, e.g.::

                [
                    'NOKLTE:LNCEL',
                    'com.nokia.srbts.nrbts:NRCELL'
                ]

            If specified, the reset is triggered only on the matching objects or the matching descendant objects in
            the operation scope. The operation scope is defined in ``dist_names`` and/or ``working_sets`` parameters.
            It is possible to define multiple target object classes if the reset object class is the same.
            If not specified, the reset is triggered on the object instances defined in ``dist_names`` and/or
            ``working_sets`` parameters.
        :param string|list(string) parameters: Specifies the parameter values for each object class that are reset,
            e.g.::

                [
                    'NOKLTE:LNCEL.gracefulCellShutDown=true',
                    'com.nokia.srbts.nrbts:NRCELL.gracefulCellShutDown=false'
                ]

            If not specified, the default parameter values are used.
        :param bool dry_run: Specifies whether the reset is triggered.
            If ``True``, the plan content can be viewed in the operation feedback to verify the scope,
            but the reset is not triggered. If ``False``, the reset is triggered.
        :param bool verbose: If ``True``, returns more detailed output from executed operation.
        :param string schedule: :meth:`prepare_schedule` method should be used to obtain correct value.
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails.
        :param int timeout: Timeout for executing operation.
        :param bool allow_vcu_reset: Prevents accidental resets on vCU.
            When ``False``, vCUs are excluded from the operation.
            When ``True``, vCUs reset plan is created, and the impacted vDUs for each vCU are listed.
            The option is supported since `24R3-NM`.
        :param string alias: NetAct instance name. Default value is ``default``.
        :return: Operation output.
        """
        if allow_vcu_reset:
            allow_vcu_reset = to_boolean(allow_vcu_reset)
        return self.store.get(alias).reset_ne(
            dist_names, working_sets, class_filter_include, parameters, dry_run,
            to_boolean(verbose), schedule, to_boolean(ignore_errors),
            time_to_seconds(timeout), allow_vcu_reset)

