    def integrate_cloud(self, cloud_id=None, ignore_errors=False, timeout=7200, alias=None,
                        cloud_dn=None, parameters=None):
        """
        This workflow operation integrates a single cloud object based on the given cloud ID for Nokia 5G Cloud RAN
        Cloud-Native Network Functions (CNFs). CLOUD and K8SAPI objects with the Kubernetes configuration property
        are created into the NetAct System Data Access (NASDA) database under the PLMN-PLMN root object. Integrated
        objects are visible in the Monitor application. As a precondition you need to import Kubernetes configuration
        (kubeconfig) YAML file content to the Security Sensitive Data (SSD).

        .. note::
            ``cloud_id`` parameter is valid before release NA 24R1, later on ``cloud_dn``
            must be used (as a named argument)

        :param string cloud_id: Instance identifier of CLOUD object, e.g. ``1``
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails.
        :param int timeout: Timeout for executing operation.
        :param string cloud_dn: DN of CLOUD object, e.g. ``PLMN-PLMN/CLOUD-1``
        :param dict parameters: Optional parameters not exposed at the method level but accepted by CLI,
            e.g.::

                {
                    '-cloudType': 'Other than Red Hat OCP',
                    '-version': 'some.version'
                }

        :param string alias: NetAct instance name. Default value is ``default``
        :return: Operation output.
        """
        return self.store.get(alias).integrate_cloud(cloud_id=cloud_id,
                                                     ignore_errors=to_boolean(ignore_errors),
                                                     timeout=time_to_seconds(timeout),
                                                     cloud_dn=cloud_dn,
                                                     parameters=parameters)

    def deintegrate_cloud(self, cloud_id=None, root_id='PLMN', force_deintegrate=False, delete_related_cnfs=True,
                          ignore_errors=False, timeout=7200, alias=None, cloud_dn=None):
        """
        Caution: This operation cannot be undone. This workflow operation deintegrates a single cloud object based on
        the given Cloud ID for Nokia 5G Cloud RAN Cloud-Native Network Functions (CNFs). CLOUD and K8SAPI objects with
        the Kubernetes configuration property are deleted from the NetAct System Data Access (NASDA) database under
        the PLMN-PLMN root object. Kubernetes configuration (kubeconfig) content is deleted from the Security Sensitive
        Data (SSD). If Force deintegrate is used, then CLOUD object is deleted even if it is connected to any CNFs.
        If Delete related CNF objects is used, also CNFs connected to the CLOUD object are deleted from the actual
        configuration.

        .. note::
            ``cloud_id`` and ``root_id`` parameters are valid before release NA 24R1, later on ``cloud_dn``
            only must be used (as a named argument)

        :param string cloud_id: Instance identifier of CLOUD object, e.g. ``1``
        :param string root_id: Instance identifier of the root object of the CLOUD object., e.g. ``WEST``
        :param bool force_deintegrate: Force to delete the CLOUD object even if it is connected to any CNFs.
        :param bool delete_related_cnfs: Deletes the CNFs connected to the CLOUD object from the actual configuration.
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails.
        :param int timeout: Timeout for executing operation.
        :param string cloud_dn: DN of CLOUD object, e.g. ``PLMN-WEST/CLOUD-theone``
        :param string alias: NetAct instance name. Default value is ``default``.
        :return: Operation output.
        """
        return self.store.get(alias).deintegrate_cloud(cloud_id=cloud_id,
                                                       root_id=root_id,
                                                       force_deintegrate=to_boolean(force_deintegrate),
                                                       delete_related_cnfs=to_boolean(delete_related_cnfs),
                                                       ignore_errors=to_boolean(ignore_errors),
                                                       timeout=time_to_seconds(timeout),
                                                       cloud_dn=cloud_dn)

    def prepare_cnf_plan(self, plan_name, dist_name, replace_existing_values=False, cluster_preparation_values=None,
                         prerequisites_values=None, main_chart_values=None, verbose=True, ignore_errors=False,
                         timeout=7200, alias=None):
        """
        This workflow operation prepare the deployment plan for Nokia 5G Cloud RAN Cloud-native network
        functions (CNFs) for vDU and/or vCU. Base64 encode values-override yaml file names for a single CNF object
        for Nokia Cloud RAN CNF vDU/vCU deployment plan. Re-run operation for each planned CNF objects one by one.
        The planned CNF configurations can be further modified and finalized by using Configurator tools.

        :param string plan_name: CNF RAML Plan filename.
        :param string dist_name: Specifies the scope of the operation, e.g. ``PLMN-PLMN/CNF-1``.
        :param bool replace_existing_values: Specifies whether the existing base64 encoded values-override file names
            in plan for the CNF object are replaced with defined input file names before saving the plan.
        :param string cluster_preparation_values: Specifies the Cloud Native Network function (CNF) optional cluster
            preparation yaml file name to be base64 encoded. Encoded file name is filled to the deployment plan in
            deploymentProfile/values parameter in structure 1. If the full file path is not specified, the default
            path is ``var/opt/oss/global/racops/import``.
        :param string prerequisites_values: Specifies the Cloud Native Network function (CNF) optional prerequisites
            yaml file name to be base64 encoded. Encoded file name is filled to the deployment plan in
            deploymentProfile/values parameter in structure 2. If the full file path is not specified, the default
            path is ``var/opt/oss/global/racops/import``.
        :param string main_chart_values: Specifies the Cloud Native Network function (CNF) mandatory main chart yaml
            file name to be base64 encoded. Encoded file name is filled to the deployment plan in
            deploymentProfile/values parameter in structure 3. If the full file path is not specified, the default
            path is ``var/opt/oss/global/racops/import``.
        :param bool verbose: If True, returns more detailed output from executed operation.
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails.
        :param int timeout: Timeout for executing operation.
        :param string alias: NetAct instance name. Default value is ``default``.
        :return: Operation output.
        """
        return self.store.get(alias).prepare_cnf_plan(plan_name, dist_name, replace_existing_values,
                                                      cluster_preparation_values, prerequisites_values,
                                                      main_chart_values, verbose, to_boolean(ignore_errors),
                                                      time_to_seconds(timeout))

