    def send_to_network(self, file_name, local_dir=None, remote_dir=None,
                        verbose=True, ignore_errors=False, timeout=7200, alias=None, cleanup=True):
        """
        The input file which may contain only one managed object with multiple parameters is sent to the network.
        Dependent objects (e.g. adjacencies) of the managed object are not created/deleted/updated.

        :param string file_name: Specifies the name of the RAML2 file containing one managed object to be created/deleted/updated.
            The input file must contain only one managed object, but can contain multiple parameters. Parameter values must be of internal
            format (not UI format). Qualified class abbreviations must be used (e.g. ``NOKRNC:WCEL`` instead of ``WCEL``).
            If ``local_dir`` is not provided, then the given ```file_name`` must exist on NetAct under ``remote_dir``.
        :param string local_dir: If set, then the given ``file_name`` is copied from it to NetAct before executing the command.
        :param string remote_dir: Specifies directory under which ``file_name`` must exist on NetAct.
            The default path is ``/var/opt/oss/global/racops/import/``.
        :param bool verbose: If ``True``, returns more detailed output from executed operation.
        :param bool ignore_errors: If ``True``, shows warnings instead of raising errors when operation fails.
        :param int timeout: Timeout for executing operation.
        :param bool cleanup: Specifies if the uploaded file has to be removed from NetAct upon completion
        :param string alias: NetAct instance name. Default value is ``default``
        :return: Operation output.
        """
        return self.store.get(alias).send_to_network(
            file_name, local_dir, remote_dir, to_boolean(verbose), to_boolean(ignore_errors),
            time_to_seconds(timeout), to_boolean(cleanup))

    @staticmethod
    def prepare_schedule(date=None, time_of_day=None, repetition=None, start=None, end=None, interval=None):
        """
        There are 3 ways to specify the time when operation should be executed:
            - setting ``date`` parameter
            - setting ``time_of_day``, ``repetition``, ``start`` and ``end`` parameters for periodic schedule
            - setting ``interval``, ``start`` and ``end`` parameters for periodic schedule

        Only one of these configurations should be used.
        In case of setting too many parameters (from different configurations),
        the first fully specified configuration is used.

        :param datetime date: Specifies date and time at which the operation should be executed
            (if this parameter is set, the rest of parameters specifying the time of execution is ignored).
        :param string time_of_day: Specifies the time of the day at which operation should be executed
            (if this parameter is set, ``repetition``, ``start`` and ``end`` parameters should be set too).
        :param int|string|list(string) repetition: Specifies days at which the operation should be executed
            (if this parameter is set, ``time_of_day``, ``start`` and ``end`` parameters should be set too).
            Possible values:

                - the number of the day within a month (1..31)
                - ``daily`` - the operation will be executed every day,
                - the list containing some values from: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]

        :param datetime start: Specifies the date and time from which the periodic schedule should start.
        :param datetime end: Specifies the date and time at which the periodic schedule should end.
        :param string interval: Specifies the length of the periodic schedule interval in format "hhh:mm".
            (if this parameter is set, ``start`` and ``end`` parameters should be set too).
        :return: schedule option value
        """
        return Netact.prepare_schedule(date, time_of_day, repetition, start, end, interval)

    def import_build(self, build_or_file_path, mo_type='MRBTS', version_id=None, release=None, alias=None,
                     clean_temp_storage=False, ccr=None):
        """
        Perform a basic import of a software package to NetAct:
         - check if build is already imported (if so - no need to import it again)
         - if not, try to import build from temporary storage, i.e., without uploading the file
         - if the previous step fails - upload build to NetAct temporary storage and try to import it again

        .. note::
            This KW uses a command available in `swmCLI.sh` since NetAct 20 SP2011

        Package ``versionID`` is displayed in the output when the import is completed.

        :param string build_or_file_path: name of a build in NetAct software temp storage
            (``/d/oss/global/swmanager/swm_temp/``), e.g., ``SBTS22R1_ENB_0000_000089_000000.zip``,
            or path to local SW package, e.g., ``/home/ute/SBTS22R1_ENB_0000_000089_000000.zip``
        :param string mo_type: managed object type
        :param string version_id: software package argument. Only one value in ``versionID`` can be used,
            e.g., ``SBTS00_ENB_9999_201215_000009``
        :param string|list(string) release: software package argument. A string or a list can be used,
            e.g., ``Tl17``, or ``['TL16', 'TL16A', 'TL17']``
        :param bool clean_temp_storage: specifies if SW package has to be deleted from NetAct software
            temporary storage after import (applies only to SW packages uploaded from a local machine)
        :param string alias: Netact instance name. Default value is ``default``
        :param bool ccr: enables/disables distribution to Central Container Registry (CCR)
            if supported by ``mo-type``. If not specified, distribution to CCR is executed only for packages
            imported for CNF ``mo-type``
        """
        if ccr:
            ccr = to_boolean(ccr)
        return self.store.get(alias).import_build(
            build_or_file_path,
            mo_type=mo_type,
            version_id=version_id,
            release=release,
            clean_temp_storage=to_boolean(clean_temp_storage),
            ccr=ccr,
        )

