    def insert_module(self, feature_names=None, enable_selected_features=True,
                      repeat_daily_at=None, timeout=120, alias=None, **module_attributes):
        """
        Insert new SWAM module.

        :param list(string) feature_names: Feature names to be enabled/disabled
            (all features are enabled by default).
        :param bool enable_selected_features:
            If ``True``, enables features with given names and  leaves all other features disabled.
            If ``False``, enables all other features and leaves features with given names disabled.
        :param string|datetime.time repeat_daily_at: Daily report generation time (04:00 by default).
            String in HH:MM format.
        :param int timeout: Timeout for retrying update until API returns the correct module.
        :param string alias: Netact instance name. Default value is ``default``.
        :param \\** module_attributes: Module attributes in kwargs format.
            Mandatory attributes: ``moduleName``, ``measurementType`` and ``technology``.
        :return: Detailed module configuration data transfer object (moduleConfigurationDto).
        :rtype: CompoundValue
        """
        return self.store.get(alias).insert_module(feature_names, to_boolean(enable_selected_features),
                                                   repeat_daily_at, time_to_seconds(timeout), **module_attributes)

    def update_module(self, module, feature_names=None, enable_selected_features=True,
                      verification_delay=2, timeout=120, alias=None):
        """
        Update existing SWAM module.

        :param CompoundValue module: Detailed single module. List of modules can be obtained
            using :meth:`get_modules` with ``detailed=True``.
            Note that a single item is expected here, not the whole list.
        :param list(string) feature_names: Feature names to be enabled/disabled.
            If this argument is not used - features are left unchanged.
            If this argument is given - at least one feature is required.
        :param bool enable_selected_features:
            If ``True``, enables features with given names and leaves all other features disabled.
            If ``False``, enables all other features and leaves features with given names disabled.
        :param int verification_delay: Seconds between updating the module and downloading
            the module from API for comparison.
        :param int timeout: Timeout for retrying update until API returns the correct module.
        :param string alias: Netact instance name. Default value is ``default``.
        :return: Detailed module configuration data transfer object (moduleConfigurationDto).
        :rtype: CompoundValue
        """
        return self.store.get(alias).update_module(module, feature_names, to_boolean(enable_selected_features),
                                                   int(verification_delay), time_to_seconds(timeout))

    def generate_reports(self, module, recheck_interval=20, max_retries=20,
                         trigger='GENERATE_REPORT_ON_DEMAND', day=0, alias=None):
        """
        Generate SWAM reports and wait for generation to complete.

        **Example output**::

            {
                'id': 11864,
                'startTimestamp': '2021-01-28T18:47:15.381+02:00',
                'finishTimestamp': '2021-01-28T18:47:35.037+02:00',
                'state': 'FINISHED',
                'dailyReportId': 14301,
                'detailedReportId': 14302,
                'aggregatedReportId': 14303,
                'summaryReportId': 14304,
                'thresholdReportId': -1,
                'moduleId': 22,
                'dailyExecutionTime': 12899,
                'periodicExecutionTime': 1729
            }

        :param dict|CompoundValue module: Single module. List of modules can be obtained
            using :meth:`get_modules`. Note that a single item is expected here, not the whole list.
        :param int recheck_interval: Interval between checking report generation task status.
        :param int max_retries: Maximum number of rechecks.
        :param string trigger: Allowed values: ``GENERATE_REPORT_TASK``, ``LICENSE_MANAGER_NOTIFICATION``,
            ``HARDLOCK_SCHEDULER_TASK``, ``GENERATE_REPORT_REMOTE_SERVICE``, ``GRACE_PERIOD_CAPACITY_CHANGED``,
            ``HASH_FAIL``, ``GENERATE_REPORT_ON_DEMAND``.
        :param int|string|datetime.date day: Day or day indicating the end of period that has to be covered in report.
            Allowed values: ``0`` for today, ``-1`` for yesterday and so on (the NetAct time zone is included)
            or YYYY-mm-dd e.g. ``2020-02-20``.
        :param string alias: Netact instance name. Default value is ``default``.
        :return: Reports generation status (taskStatusDto).
        :rtype: CompoundValue
        """
        return self.store.get(alias).generate_reports(module, int(recheck_interval), int(max_retries), trigger, day)

    def start_reports_generation(self, module, trigger='GENERATE_REPORT_ON_DEMAND', day=0, alias=None):
        """
        Start SWAM reports generation asynchronously.

        :param dict|CompoundValue module: Single module. List of modules can be obtained
            using :meth:`get_modules`. Note that a single item is expected here, not the whole list.
        :param string trigger: Allowed values: ``GENERATE_REPORT_TASK``, ``LICENSE_MANAGER_NOTIFICATION``,
            ``HARDLOCK_SCHEDULER_TASK``, ``GENERATE_REPORT_REMOTE_SERVICE``, ``GRACE_PERIOD_CAPACITY_CHANGED``,
            ``HASH_FAIL``, ``GENERATE_REPORT_ON_DEMAND``.
        :param int|string|datetime.date day: Day or day indicating the end of period that has to be covered in report.
            Allowed values: ``0`` for today, ``-1`` for yesterday and so on (the NetAct time zone is included)
            or YYYY-mm-dd e.g. ``2020-02-20``.
        :param string alias: Netact instance name. Default value is ``default``.
        :return: Task id.
        :rtype: int
        """
        return self.store.get(alias).start_reports_generation(module, trigger, day)

    def wait_for_reports(self, task_id, recheck_interval=20, max_retries=6, alias=None):
        """
        Wait for SWAM reports generation task specified by given ID to complete.

        :param int task_id: Can be obtained using :meth:`start_report_generation`.
        :param int recheck_interval: Interval between checking report generation task status.
        :param int max_retries: Maximum number of rechecks.
        :param string alias: Netact instance name. Default value is ``default``.
        :return: Reports generation status (taskStatusDto).
            Example output the same as for :meth:`generate_reports`.
        :rtype: CompoundValue
        """
        return self.store.get(alias).wait_for_reports(int(task_id), int(recheck_interval), int(max_retries))

