    def get_pm_counters(self, technology, measurement, counters, filter_by, mo_names,
                        object_aggregation, time_aggregation, time_filter='absolute', alias=None, **kwargs):
        """
        Perform on-the-fly report and return PM counters statistics.

        | Configuration of parameters and their values correspond to the `Add To New Board` wizard \
        of `Performance Manage+` application.
        | Technology, measurement and counters values are accessible in `View Details` of each counter.

        .. note::

            No idea how to configure parameter?
            Just set a dummy value, run script and follow a hint returned in the exception.

        Example output::

            [
                {
                    'CHNG_TO_CELL_AVAIL': 1.0,
                    'CHNG_TO_CELL_PLAN_UNAVAIL': 1.0,
                    'dn': 'PLMN-PLMN/MRBTS-1/LNBTS-1/LNCEL-1',
                    'lnbts_name': '1',
                    'lncel_gid': '100011',
                    'lncel_name': '1',
                    'mrbts_name': '1',
                    'period_start_time': '2022-02-22 09:00:00.0'
                },
                {
                    'CHNG_TO_CELL_AVAIL': 0.0,
                    'CHNG_TO_CELL_PLAN_UNAVAIL': 1.0,
                    'dn': 'PLMN-PLMN/MRBTS-1/LNBTS-1/LNCEL-2',
                    'lnbts_name': '1',
                    'lncel_gid': '100012',
                    'lncel_name': '2',
                    'mrbts_name': '1',
                    'period_start_time': '2022-02-22 09:00:00.0'
                },
                {
                    'CHNG_TO_CELL_AVAIL': 1.0,
                    'CHNG_TO_CELL_PLAN_UNAVAIL': 2.0,
                    'dn': 'PLMN-PLMN/MRBTS-1/LNBTS-1/LNCEL-3',
                    'lnbts_name': '1',
                    'lncel_gid': '100013',
                    'lncel_name': '3',
                    'mrbts_name': '1',
                    'period_start_time': '2022-02-22 09:00:00.0'
                }
            ]

        :param string technology: Technology name, e.g., ``LNBTS-NSN LTE Base Transceiver Station``
        :param string measurement: Measurement name, e.g., ``LTE Cell Availability``
        :param string|list(string) counters: Counter identifier(s), e.g.,
            ``CHNG_TO_CELL_AVAIL`` or ``['CHNG_TO_CELL_AVAIL', 'CHNG_TO_CELL_PLAN_UNAVAIL']``.
            Accepts also ``ALL`` what means all counters of the set ``measurement``.
        :param string filter_by: Item from `Filter by` list at `Object selection` stage
            of `Add To New Board` wizard, e.g., ``MRBTS``.
        :param string|list(string) mo_names: Managed object name(s), e.g., ``PLMN-PLMN/MRBTS-1``
            or ``['PLMN-PLMN/MRBTS-1', 'PLMN-PLMN/MRBTS-2']``.
            Item from `Available objects` list at `Object selection` stage of `Add To New Board` wizard.
        :param string object_aggregation: Object aggregation name, e.g., ``PLMN/MRBTS``.
            Item from `Object` list at `Aggregation` stage of `Add To New Board` wizard.
        :param string time_aggregation: Time aggregation name, e.g., ``RAW``.
            Item from `Time` list at `Aggregation` stage of `Add To New Board` wizard.
        :param string time_filter: Corresponds to `Time selection` stage of `Add To New Board` wizard.
            Allowed value: ``relative``, ``absolute``, ``realtime``, ``today``, ``currentMonth``
            or ``previousMonth``.
        :param string alias: Netact instance name. Default value is ``default``.

        :kwargs: Depend on the set ``time_filter`` as follows:

            - time_from (string): Mandatory for ``relative`` time filter. \
                Allowed values: ``NOW`` or ``MIDNIGHT``.
            - time_amount (int): Mandatory for ``relative`` time filter.
            - time_period (string): Mandatory for ``relative`` time filter. \
                Allowed values: ``MIN``, ``HOUR``, ``DAY``, ``WEEK`` or ``MONTH``.
            - start_time (datetime): Mandatory for ``absolute`` time filter.
            - end_time (datetime): Mandatory for ``absolute`` time filter.
            - look_back_period (int): Mandatory for ``realtime`` time filter (in minutes).

        :return: PM counters statistics.
        :rtype: list(dict)
        """
        if 'time_amount' in kwargs:
            kwargs['time_amount'] = int(kwargs['time_amount'])
        if 'look_back_period' in kwargs:
            kwargs['look_back_period'] = int(kwargs['look_back_period'])
        return self.store.get(alias).get_pm_counters(
            technology, measurement, counters, filter_by, mo_names,
            object_aggregation, time_aggregation, time_filter, **kwargs)

