    def get_fast_pass_packages(self, unique=False, all=False, latest=None, fp=None,
                               artifact=None, stdout=True, timeout=120, alias=None):
        """
        Get information about fast pass packages.

        The ``--list`` option is used by default - query for all installed packages.

        :param bool unique: If True, returns only the latest installed fast pass packages
            for each package name. Valid only for default ``--list`` option.
        :param bool all: Set ``--all`` option to query for all packages, including packages
            that are imported but not deployed yet. Higher priority than ``--list`` option.
        :param int|string latest: Set ``--latest`` option to query for specified number of latest installed packages.
            Support the number within the range of [1, 10000]. Higher priority than ``--list`` and ``--all`` options.
        :param string fp: Set ``--fp`` option to query for detailed information of specified fast pass package.
            Higher priority than ``--list``, ``--all`` and ``--latest`` options.
        :param string artifact: Set ``--artifact`` option to query for detailed info of specified adaptation fragment.
            The artifact id is the id defined in FIT: fragment/type/adpatationId/adaptationrelease[/buildnumber],
            can be obtained by ``--fp`` option. Highest priority of all available options.
        :param bool stdout: If True, returns stdout as a string,
            otherwise converts it to dict (for ``--fp`` and ``--artifact``) or list of dicts (for other options).
        :param int timeout: Timeout for executing command.
        :param string alias: Netact instance name. Default value is ``default``.
        :return: Command output. Type depends on ``stdout`` parameter.
        :rtype: string|dict|list(dict)
        """
        return self.store.get(alias).get_fast_pass_packages(
            to_boolean(unique),
            to_boolean(all),
            latest,
            fp,
            artifact,
            to_boolean(stdout),
            time_to_seconds(timeout)
        )

    def prepare_unified_pnp_coam_site(self, plan_name, input_file=None, file_format='RAML2', profiler_file='/var/opt/oss/global/racops/import/',
                                      activate_site_template=True, ui_values=False, gps_identification_used=False,
                                      gps_tolerance=None, maintenance_region_dn=None, verbose=True, ignore_errors=False, timeout=600,
                                      alias=None, distribution=None, helm_test=None, local_dir=None, cleanup=True):
        """
        This operation:
        1. Creates BTSs site plan
        2. Applies site template to the plan
        3. Validates the plan
        4. Sends identification parameters to AC Service.

        Netact default import directory ``/var/opt/oss/global/racops/import/``.

        :param string plan_name: Specifies a plan name
        :param string input_file: Specifies a full path to plan or a name of a plan inside Netact default import directory,
            or, when used with ``local_dir``, a name of a local plan file. If not provided,
            operation will be executed on the existing plan
        :param string file_format: Indicates the CSV or RAML2 file format with COAM BTS planned configuration.
            Defaults to ``RAML2``
        :param string profiler_file: Profile file is required in case the CSV format is chosen.
            Defaults to ``/var/opt/oss/global/racops/import/``
        :param bool activate_site_template: Specifies if Site Template is used in planning operation.
            Defaults to ``True``
        :param bool ui_values: Specifies if parameter values are given as UI values in an imported file with COAM BTS planned configuration.
            If this parameter is not defined, internal values are used.
            Defaults to ``False``
        :param bool gps_identification_used: Enable to using GPS based identification. Site object must to be assigned.
            Defaults to ``False``
        :param int gps_tolerance: Defines the allowed deviation (meter) between the reported GPS location of the NE
            and the location defined int Site object. **Range**: 1..5000.
            No default value
        :param string maintenance_region_dn: Defines DN of the Maintenance Region to be assigned to the NEs that do not have it specified
            in an imported file with planned configuration. An example of a valid format is ``MRC-1/MR-NE3S``.
            No default value
        :param bool verbose: If ``True``, KW returns a detailed output from executed operation
        :param bool distribution: Allows to distribute CNF SW images to Container Registries before CNF deployment.
            ``True`` by default (provided that the option is supported by ``racclimx.sh``)
        :param bool helm_test: Specifies if helm test is performed during deployment of CNFs. ``True`` by default
        :param str local_dir: If provided, then the given ``input_file`` is copied from this path to NetAct's default import directory
            before executing the command
        :param bool ignore_errors: If ``True``, KW shows warnings instead of raising errors when operation fails
        :param int timeout: Timeout for executing command
        :param bool cleanup: Specifies if the uploaded file has to be removed from NetAct upon completion
        :param string alias: Netact instance name. Default value is ``default``
        """
        if distribution:
            distribution = to_boolean(distribution)
        if helm_test:
            helm_test = to_boolean(helm_test)
        return self.store.get(alias).prepare_unified_pnp_coam_site(
            plan_name=plan_name,
            input_file=input_file,
            file_format=file_format,
            profiler_file=profiler_file,
            activate_site_template=to_boolean(activate_site_template),
            ui_values=to_boolean(ui_values),
            gps_identification_used=to_boolean(gps_identification_used),
            gps_tolerance=gps_tolerance,
            maintenance_region_dn=maintenance_region_dn,
            verbose=to_boolean(verbose),
            ignore_errors=to_boolean(ignore_errors),
            timeout=time_to_seconds(timeout),
            distribution=distribution,
            helm_test=helm_test,
            local_dir=local_dir,
            cleanup=to_boolean(cleanup)
        )

    def collect_symptom_data_by_component(self,
                                          component,
                                          local_dir_path,
                                          log_all=False,
                                          include_systeminfo=False,
                                          alias=None):
        """
        Collect and download symptom data for a given component.

        .. note::
            - Nokia recommends collecting symptom data from 3 or fewer components each time.
            - For information on the supported components, use :meth:`get_supported_symptom_collector_components` keyword.

        .. warning::
            Before symptom collection:
            - Make sure that the disk space on the global disk is enough. Symptom collection data
                can be up to 1000 MB or more for each component, depending on log level and NetAct configuration.
            - Collecting symptom data may affect system resources temporarily, like CPU usage, memory usage,
                disk I/O and so on. Make sure that enough system resource is available and avoid performing symptom collection
                when system is in high load.

        :param str|list(str) component: A selected component (or a list thereof)
            such as ``software-manager``, ``mediation-nwi3``, etc.
        :param str local_dir_path: A local directory to which collected files will be saved as ZIP
        :param bool log_all: Set to ``True`` to collect all the information, including big files such as heapdump
        :param bool include_systeminfo: Set to ``True`` to collect system information such as NetAct release version
        :param str alias: Netact instance name. Default value is ``default``
        :return: Path to downloaded ZIP file
        :rtype: str
        """
        return self.store.get(alias).collect_symptom_data_by_component(component,
                                                                       local_dir_path,
                                                                       log_all=to_boolean(log_all),
                                                                       include_systeminfo=to_boolean(include_systeminfo))

    def get_supported_symptom_collector_components(self, alias=None):
        """
        Get list of supported Symptom Collector components

        :param str alias: Netact instance name. Default value is ``default``
        :return: list of supported components
        :rtype: list
        """
        return self.store.get(alias).get_supported_symptom_collector_components()

    def import_ssd(self, input_file, file_format='RAML2', overwrite=False, alias=None):
        """
        Import SSD detail into NetAct by reading the data from a RAML2.1 or a JSON file.

        :param str input_file: path to input data file
        :param string file_format: Indicates the ``JSON`` or ``RAML2`` (RAML2.1) file format
        :param bool overwrite: indicates if the operation overwrites the previous contents, defaults to ``False``.
            It must be set to ``True`` to overwrite the previous contents. If ``overwrite`` is set to ``False``
            and SSD is already available in NetAct for given DNs in the input file, then the operation fails
        :param str alias: NetAct instance name. Default value is ``default``
        """
        return self.store.get(alias).import_ssd(input_file,
                                                file_format=file_format,
                                                overwrite=to_boolean(overwrite))

    def delete_ssd(self, scope, delete_any_mo=False, alias=None):
        """
        Delete the SSD of those DNs which were previously imported to MantaRay NM.

        .. note::
            - The underlying API does not delete the SSD content in the network element. The delete API is useful to delete
            the invalid SSD imported to MantaRay NM before provisioning to the network element
            - If one or more DN SSD details are not present, then the delete operation is partially successful.
            If all DNs do not have the SSD detail, then the operation fails completely

        :param str|list(str) scope: DN or a list of DNs subject for the operation
        :param bool delete_any_mo: Set to ``True`` to delete any managed object for the given DN which has valid SSD.
             If set to ``False``, the procedure deletes only the managed object for the given DN which is under MRBTS
        :param str alias: NetAct instance name. Default value is ``default``
        """
        return self.store.get(alias).delete_ssd(scope, delete_any_mo=to_boolean(delete_any_mo))

    def provision_ssd(self, scope, timeout=120, alias=None):
        """
        Provision the RUs SSD detail to the network element. Before triggering the operation,
        one must import SSD to MantaRay NM for the given Distinguished Name (DN).

        .. note::
            - DNs used for provisioning must be scope authorized. Otherwise, the operation ignores the DNs
            which do not have a scope.
            - The user must have SSD object provisioning permission.

        :param str|list(str) scope: DN or a list of DNs subject for the operation
        :param int|str timeout: Timeout for executing operation
        :param str alias: NetAct instance name. Default value is ``default``
        :return: Status of operation
        :rtype: dict
        """
        return self.store.get(alias).provision_ssd(scope, timeout=time_to_seconds(timeout))

    def activate_cnum(self, ne_id_value, ne_id_type='dn', ldap_access_type=None,
                      ip_type=None, include_correlated_nes=None, timeout=120, alias=None):
        """
        Perform CNUM Activation operation on a specific network element.
        Distinguished Name or Presentation Name must be specified as input for the network element.

        Example output::

            {
                "activationState": None,
                "completionTime": None,
                "errors": [],
                "statusMsg": "1 out of 1 Operation(s) scheduled are completed. "
                             "Successful = 1, Partly Successful = 0, Failed = 0, Ongoing = 0",
                "startTimeStamp": "15/06/2023 09:18:55 GMT",
                "operationStatus": "Completed"
            }

        :param string|list(dict) ne_id_value: Specifies network element(s) for which CNUM operation is to be performed:

            - If ``ne_id_type`` is ``dn``, then NE's Distinguished Name must be set (as registered in Monitor).
            - If ``ne_id_type`` is ``name``, then NE's Presentation Name must be set (as configured in NE Integration Wizard).
            - If ``ne_id_type`` is ``input_file``, then list of NEs must be specified in list(dict) format, where each dict \
            must contain at least ``dnName`` attribute:

                - dnName (string): (Mandatory) NE’s Distinguished Name.
                - ldapAccessType (string): (Optional): Allowed values: ``PREFER TLS`` or ``STARTTLS``
                - ipType (string): (Optional): Allowed values: ``IPv4`` or ``IPv6``

            If ``ldapAccessType`` and/or ``ipType`` attribute are not specified, then the values configured in
            `ldap_access_type` and/or `ip_type` are used. If `ldap_access_type` and/or `ip_type` are not specified,
            then default values supported by the specified network element type are used.
        :param string ne_id_type: Allowed values:

            - ``dn`` if NE’s Distinguished Name is set as ``ne_id_value``.
            - ``name`` if NE’s Presentation Name is set as ``ne_id_value``.
            - ``input_file`` if list of NEs is set as ``ne_id_value``.

        :param string ldap_access_type: LDAP Access type to be configured in network element while triggering CNUM
            activation operation. Allowed values ``PREFER TLS`` or ``STARTTLS``. If not specified, then the default
            LDAP Access Type supported by the specified network element type is used.
        :param string ip_type: IP type configured in network element. Allowed values: ``IPv4`` or ``IPv6``.
            If not specified, then the default IP Type supported by the specified network element type is used.
        :param string include_correlated_nes: IP type configured in network element while triggering CNUM operation.
            If ``False``, then triggered CNUM operation is performed only on the specified network element
            and not on co-related network elements even if they exist. If not set, then the default value is ``False``.
            This flag is provided for network elements that have a PARENT-CHILD correlation. That is, NADA adaptation
            parameter correlationType equals PARENT or CHILD, e.g. RNC and VNF. For such correlated network elements
            it is recommended to have same CNUM status.
        :param int timeout: Timeout for executing operation.
        :param string alias: Netact instance name. Default value is ``default``

        :return: Status of operation.
        :rtype: dict
        """
        if include_correlated_nes:
            include_correlated_nes = to_boolean(include_correlated_nes)
        return self.store.get(alias).activate_cnum(
            ne_id_value, ne_id_type, ldap_access_type, ip_type, include_correlated_nes, time_to_seconds(timeout))

