    def import_scf(self,
                   plan_name,
                   file_name,
                   local_dir=None,
                   import_type='plan',
                   set_system_template=False,
                   merge_import=False,
                   dn_prefix='PLMN-PLMN',
                   verbose=False,
                   timeout=600,
                   alias=None,
                   cleanup=True):
        """
        Convert an SBTS/5G/LTE/ASI site configuration files (SCF) to NetAct model RAML file,
            and import the file as a plan or as a site template to NetAct database.
            NetAct's default import directory: ``/var/opt/oss/global/racops/import/``.

        :param str plan_name: Plan name
        :param str|list(str) file_name: Input can be an XML file, a list of XML files, or a ZIP file containing XML files.
            ZIP file can also contain nested ZIP files. Can be used together with ``local_dir`` when a single local file is used.
            If ``local_dir`` is not provided, then a file or files specified as ``file_name`` must exist
            in NetAct under default import directory
        :param string local_dir: If provided, then the given ``file_name`` is copied from it to NetAct's default import directory
        :param str import_type: Type of import operation: ``plan`` (default) or ``siteTemplate``
        :param bool set_system_template: Determines if a system template should be assigned to imported objects
            when no other template is defined
        :param bool merge_import: Specifies if the imported plan should be merged to an existing plan
            If the value of this attribute is set to ``True`` and the ``planName`` attribute is provided,
            then the plan is merged
        :param str dn_prefix: Specifies the DN prefix to be added for the managed object DNs during the conversion,
            for example, using ``PLMN-databuild`` will result in ``PLMN-databuild/MRBTS-<ID>``. Defaults to ``PLMN-PLMN``
        :param bool verbose: If ``True``, KW returns a detailed output from executed operation
        :param int|string timeout: Timeout for executing operation
        :param bool cleanup: Specifies if the uploaded file has to be removed from NetAct upon completion
        :param str alias: NetAct instance name. Default value is ``default``
        :return: Operation's output
        :rtype: str
        """
        return self.store.get(alias).import_scf(plan_name,
                                                file_name,
                                                local_dir=local_dir,
                                                import_type=import_type,
                                                set_system_template=to_boolean(set_system_template),
                                                merge_import=to_boolean(merge_import),
                                                dn_prefix=dn_prefix,
                                                verbose=to_boolean(verbose),
                                                timeout=time_to_seconds(timeout),
                                                cleanup=to_boolean(cleanup))

